// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.Collections;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.junit.jupiter.api.Test;

/** The selector is a pure ranking rule: dominance first, then lowest expected price, registry order last. */
class LmdbNativeSelectorTest {

	private static final LmdbNativeStaticPrior PRIOR = LmdbNativeStaticPrior.DEFAULT;

	private static LmdbNativeCandidate<String> candidate(String id, double low, double expected, double high) {
		LmdbNativeCostQuote quote = LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, low, expected, high), 1_000D);
		return LmdbNativeCandidate.of(id, quote, () -> id);
	}

	@Test
	void lowestExpectedPriceWinsAmongOverlappingIntervals() {
		List<LmdbNativeCandidate<String>> candidates = List.of(
				candidate("a", 100, 500, 900),
				candidate("b", 200, 300, 950),
				candidate("c", 50, 700, 1_000));
		LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(candidates, PRIOR, -1D);
		assertThat(ranking.winner()).isEqualTo(1);
		assertThat(ranking.eliminatedBy()).containsOnlyNulls();
		assertThat(ranking.reason()).contains("Lowest expected price");
	}

	@Test
	void aCandidateWhoseWholeIntervalLiesAboveAnotherIsEliminated() {
		List<LmdbNativeCandidate<String>> candidates = List.of(
				candidate("cheap", 10, 20, 30),
				candidate("expensive", 100, 110, 120));
		LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(candidates, PRIOR, -1D);
		assertThat(ranking.winner()).isZero();
		assertThat(ranking.eliminatedBy()[1]).startsWith("Priced above cheap");
	}

	@Test
	void structuralDominanceBeatsPrice() {
		LmdbNativeCandidate<String> specialist = candidate("indexedCount", 500, 600, 700)
				.dominating(Set.of("nestedLoop"));
		List<LmdbNativeCandidate<String>> candidates = List.of(candidate("nestedLoop", 1, 2, 3), specialist);
		LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(candidates, PRIOR, -1D);
		assertThat(ranking.winner()).isEqualTo(1);
		assertThat(ranking.eliminatedBy()[0]).isEqualTo("Structurally dominated by indexedCount");
	}

	@Test
	void structuralDominanceMatchesTheBaseIdOfAVariant() {
		LmdbNativeCandidate<String> specialist = candidate("typeMatrix", 500, 600, 700)
				.dominating(Set.of("irAggregate"));
		List<LmdbNativeCandidate<String>> candidates = List.of(candidate("irAggregate(parallel)", 1, 2, 3),
				specialist);
		LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(candidates, PRIOR, -1D);
		assertThat(ranking.winner()).isEqualTo(1);
	}

	@Test
	void lastResortCompetesOnlyWhenNothingOrdinaryIsAdmitted() {
		LmdbNativeCandidate<String> fallback = candidate("genericFallback", 1, 1, 1).asLastResort();
		LmdbNativeSelector.Ranking withOrdinary = LmdbNativeSelector.rank(
				List.of(candidate("kernel", 900, 900, 900), fallback), PRIOR, -1D);
		assertThat(withOrdinary.winner()).isZero();
		assertThat(withOrdinary.eliminatedBy()[1]).startsWith("Last resort");
		LmdbNativeSelector.Ranking alone = LmdbNativeSelector.rank(List.of(fallback), PRIOR, -1D);
		assertThat(alone.winner()).isZero();
	}

	@Test
	void registryOrderBreaksExactTiesOnly() {
		List<LmdbNativeCandidate<String>> candidates = List.of(candidate("second", 10, 50, 90),
				candidate("first", 10, 50, 90));
		assertThat(LmdbNativeSelector.rank(candidates, PRIOR, -1D).winner()).isZero();
		List<LmdbNativeCandidate<String>> reversed = List.of(candidates.get(1), candidates.get(0));
		assertThat(LmdbNativeSelector.rank(reversed, PRIOR, -1D).winner()).isZero();
	}

	@Test
	void declarationOrderDoesNotChangeAPricedDecision() {
		List<LmdbNativeCandidate<String>> candidates = List.of(
				candidate("a", 100, 500, 900),
				candidate("b", 200, 300, 950),
				candidate("c", 50, 700, 1_000));
		for (int rotation = 0; rotation < candidates.size(); rotation++) {
			List<LmdbNativeCandidate<String>> rotated = new java.util.ArrayList<>(candidates);
			Collections.rotate(rotated, rotation);
			LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(rotated, PRIOR, -1D);
			assertThat(rotated.get(ranking.winner()).id()).as("rotation %s", rotation).isEqualTo("b");
		}
	}

	@Test
	void aSliceProratesStreamingWorkButNotStartupWork() {
		LmdbNativeCostQuote frontLoaded = new LmdbNativeCostQuote(
				LmdbNativeCostVector.point(Feature.HASH_BUILD_ROW, 500D),
				LmdbNativeCostVector.point(Feature.SCANNED_ROW, 1_000D), 1_000D, false, false);
		LmdbNativeCostQuote streaming = LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.point(Feature.INTERPRETED_ROW, 1_000D), 1_000D);
		List<LmdbNativeCandidate<String>> candidates = List.of(
				LmdbNativeCandidate.of("hash", frontLoaded, () -> "hash"),
				LmdbNativeCandidate.of("stream", streaming, () -> "stream"));
		// whole result: hash build 500 × 45 ns + 1000 scanned rows beats 1000 interpreted rows at 44 ns; both pay
		// the same output materialisation
		assertThat(LmdbNativeSelector.rank(candidates, PRIOR, -1D).winner()).isZero();
		// first ten rows: the hash build is still paid in full, the streaming candidate pays one percent
		assertThat(LmdbNativeSelector.rank(candidates, PRIOR, 10D).winner()).isEqualTo(1);
	}

	@Test
	void anUnboundedQuoteCompetesOnlyWhenNothingIsPriced() {
		LmdbNativeCandidate<String> unknown = LmdbNativeCandidate.of("wcoj",
				LmdbNativeCostQuote.ofWork(LmdbNativeWork.UNKNOWN, Double.NaN), () -> "wcoj");
		List<LmdbNativeCandidate<String>> candidates = List.of(candidate("kernel", 10, 20, 30), unknown);
		LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(candidates, PRIOR, -1D);
		// its floor of zero is not a price: the priced kernel wins even though the kernel costs more than zero
		assertThat(ranking.winner()).isZero();
		assertThat(ranking.eliminatedBy()[1]).startsWith("Unpriced");
		assertThat(ranking.nanos()[1].known()).isFalse();
		LmdbNativeSelector.Ranking alone = LmdbNativeSelector.rank(List.of(unknown), PRIOR, -1D);
		assertThat(alone.winner()).isZero();
	}
}
